sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    //MSSRBXCE-494: BR-#3 Started
	if(isJsonString(current.swb_payload)){

		var inPayload = JSON.parse(current.swb_payload);
		var blocktrades= {};
		for(var i=0;i<inPayload.length;i++){
			var blocktrade = inPayload[i].Block_Trade_ID.toString();

			if (blocktrade!="" && blocktrades[blocktrade]==undefined){
				blocktrades[blocktrade]=[inPayload[i]]; //get the list of unique blocktrades
			} else {
				blocktrades[blocktrade].push(inPayload[i]);
			}
		}

		//create swb payload for every blocktrade
		for(var key in blocktrades){

			var grInstr = new GlideRecord('x_hsb11_hsbcmss_eh_swb_final_payload_responses');
			grInstr.initialize();
			grInstr.parent_email_case=current.sys_id;
			grInstr.payload = JSON.stringify(blocktrades[key]);
			grInstr.client_response="Manual Instructions Received";
			grInstr.financial_object_from_payload=key.toString();
			grInstr.financial_object_type="Block Trade";
			grInstr.insert();
		}

	}else{
		current.work_notes = "Not a valid JSON - cannot convert Allocation Instructions into actionable items";
		current.update();
	}

function isJsonString(str){
	try {
		JSON.parse(str);
	} catch(e){
		return false;
	}
	return true;
}
//MSSRBXCE-494: BR-#3 Ended
})(current, previous);
